// App data layer — the DB client lives here.
//
// This starter ships without any tables, so the wiring is stubbed out. `getDb()`
// returns a Drizzle client bound to the app's `schema`. Enable it when you add
// your first table (see `drizzle/START_HERE.md`):
//
//   1. Define tables in `drizzle/schema.ts`.
//   2. Add `drizzle-orm` (dependency) and `drizzle-kit` (devDependency), a
//      `"db:generate": "drizzle-kit generate"` script, and a `drizzle.config.ts`
//      with `export default createDrizzleConfig()` from
//      `@agent-native/core/db/drizzle-config`.
//   3. Uncomment the lines below, run `pnpm db:generate`, then restart the dev
//      server so the framework applies the new migration on boot.
//
// import { createGetDb } from "@agent-native/core/db";
// import * as schema from "../drizzle/schema";
//
// export const getDb = createGetDb(schema);
// export { schema };

export {};
